import{z as A,x as p,o as t,c as d,q as o,j as E,D as e,d as l,s as i,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"SSH 协议","description":"","frontmatter":{"title":"SSH 协议","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ssh-protocol.md","filePath":"cs/ssh-protocol.md","lastUpdated":1791413859000}'),S={name:"cs/ssh-protocol.md"};function T(P,a,B,h,C,F){const r=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="ssh-协议" tabindex="-1">SSH 协议 <a class="header-anchor" href="#ssh-协议" aria-label="Permalink to &quot;SSH 协议&quot;">​</a></h1><div class="epigraph"><p>SSH 在一条 TCP 上先密钥交换再开信道：会话、端口转发、SFTP 都是信道类型，不是三个端口三个协议。</p><footer>—— 据 RFC 4253 SSH 运输；RFC 4254 连接协议整理</footer></div><p><a href="/cs/http-tls-entry">TLS 入口</a> 保护 HTTP。<a href="/cs/spf-dkim-dmarc">上一课</a> 是邮件。缺口是<strong>交互登录与隧道的 SSH</strong>：版本交换、KEX、认证、多信道。本课不把 NTP 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>telnet 明文。SSH：二进制包，运输层加密完整性，然后用户认证（公钥/密码），再 multiplex 信道。端口转发把其它应用塞进这条管道，像应用层 GRE。与 QUIC 对照：都有加密+多流，SSH 更老、跑 TCP，有 TCP HOL。主机密钥钉防中间人，类似证书钉但常 TOFU。</p><p><span class="marginnote">「多路复用」翻译一下：认证完成后那条加密连接并不只服务一个终端——每个逻辑流（shell、转发的端口、SFTP）各领一个信道编号，数据包上带着编号走同一条 TCP，接收端按编号分拣。像一条高速公路划出多条车道：路面只有一条，车流互不挡道。</span></p><p>不要把 ssh 命令行选项当协议规范。</p><p><span class="marginnote">RFC 4251–4254。本课不写爆破密码的操作。</span></p><h3 id="加密运输加多信道" tabindex="-1">加密运输加多信道 <a class="header-anchor" href="#加密运输加多信道" aria-label="Permalink to &quot;加密运输加多信道&quot;">​</a></h3><p>转发是信道不是独立端口协议。主机密钥 TOFU 防中间人。TCP-over-TCP 当 VPN 有代价。Nagle 对按键有害。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：TCP 22 → KEX → 认证 → 信道。对照 HTTPS：证书 PKI vs known_hosts。与 keepalive：SSH 有应用层 ping。</p>',12)),(t(),E(n,null,{default:e(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCP%5B%22TCP%22%5D%20--%3E%20KEX%5B%22%E5%AF%86%E9%92%A5%E4%BA%A4%E6%8D%A2%22%5D%0A%20%20KEX%20--%3E%20AUTH%5B%22%E7%94%A8%E6%88%B7%E8%AE%A4%E8%AF%81%22%5D%0A%20%20AUTH%20--%3E%20CH%5B%22%E5%A4%9A%E4%BF%A1%E9%81%93%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[l("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"Nagle 对按键延迟有害，SSH 常关。窗口与流量控制在信道上。TSO 对小交互帮助有限。跳板与 ProxyJump 是会话层，不是 BGP。安全：认证失败限速，不写绕过。",-1)),a[5]||(a[5]=s("p",null,"SFTP 是子系统，不是另起 FTP 课的被动模式。",-1)),(t(),E(n,null,{default:e(()=>[i(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRANS%5B%22%E4%B8%80%E6%9D%A1%E5%8A%A0%E5%AF%86%E8%BF%90%E8%BE%93%E5%B1%82%22%5D%20--%3E%20CH1%5B%22%E4%BF%A1%E9%81%93%EF%BC%9A%E4%BA%A4%E4%BA%92%20shell%22%5D%0A%20%20TRANS%20--%3E%20CH2%5B%22%E4%BF%A1%E9%81%93%EF%BC%9A%E7%AB%AF%E5%8F%A3%E8%BD%AC%E5%8F%91%22%5D%0A%20%20TRANS%20--%3E%20CH3%5B%22%E4%BF%A1%E9%81%93%EF%BC%9ASFTP%20%E5%AD%90%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20CH1%20--%3E%20FLOW%5B%22%E6%AF%8F%E4%BF%A1%E9%81%93%E7%8B%AC%E7%AB%8B%E7%AA%97%E5%8F%A3%E4%B8%8E%E6%B5%81%E6%8E%A7%22%5D%0A%20%20CH2%20--%3E%20FLOW%0A%20%20CH3%20--%3E%20FLOW%0A%20%20FLOW%20--%3E%20SAME%5B%22%E5%85%A8%E9%83%A8%E5%A4%8D%E7%94%A8%E5%90%8C%E4%B8%80%E6%9D%A1%20TCP%20%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：把 SSH 隧道当 VPN 用。隧道里跑的应用自己做 TCP，外面 SSH 又是一层 TCP——两层各自重传、各自计时，丢包时内层还在等重传，外层已经超时重发，性能会塌得比任何一层单独存在都难看。这就是本课说的 TCP-over-TCP 代价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SSH 证书 CA 的全部。NTP 是下一课。后课默认：SSH = 加密运输 + 认证 + 多信道。</p><p>把 SSH 当通用 VPN 要接受 TCP-over-TCP 的性能。</p><p>下一课<a href="/cs/ntp">NTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一层加密运输，上面多信道。</li><li>主机密钥钉身份。</li><li>转发是信道，不是独立协议。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4253；RFC 4254。</li></ul>',7))])}const u=A(S,[["render",T]]);export{c as __pageData,u as default};
